CREATE OR REPLACE FUNCTION public.public_erp_icon() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT coalesce((SELECT variant_key FROM public.cde_selected WHERE group_key='erp_icon' AND is_primary=true AND variant_key IN ('myio','io-purple','io-black') LIMIT 1),'myio') $$; REVOKE ALL ON FUNCTION public.public_erp_icon() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_erp_icon() TO anon,authenticated; COMMENT ON FUNCTION public.public_erp_icon() IS 'Public ERP icon key only; no user information or other CDE settings.';